                __m512d sm2_w0_0 = _mm512_mul_pd(_mm512_set1_pd(1.0/5.0), k1x_w0);
        __m512d p3_w0_0 = _mm512_mul_pd(_mm512_set1_pd(3.0/40.0), k1x_w0);
        __m512d p4_w0_0 = _mm512_mul_pd(_mm512_set1_pd(44.0/45.0), k1x_w0);
        __m512d p5_w0_0 = _mm512_mul_pd(_mm512_set1_pd(19372.0/6561.0), k1x_w0);
        __m512d p6_w0_0 = _mm512_mul_pd(_mm512_set1_pd(9017.0/3168.0), k1x_w0);
        __m512d ps_w0_0 = _mm512_mul_pd(_mm512_set1_pd(35.0/384.0), k1x_w0);
        __m512d py_w0_0 = _mm512_mul_pd(_mm512_set1_pd(5179.0/57600.0), k1x_w0);
        ax_w0 = _mm512_fmadd_pd(h_w0, sm2_w0_0, yx_w0);
        __m512d sm2_w0_1 = _mm512_mul_pd(_mm512_set1_pd(1.0/5.0), k1y_w0);
        __m512d p3_w0_1 = _mm512_mul_pd(_mm512_set1_pd(3.0/40.0), k1y_w0);
        __m512d p4_w0_1 = _mm512_mul_pd(_mm512_set1_pd(44.0/45.0), k1y_w0);
        __m512d p5_w0_1 = _mm512_mul_pd(_mm512_set1_pd(19372.0/6561.0), k1y_w0);
        __m512d p6_w0_1 = _mm512_mul_pd(_mm512_set1_pd(9017.0/3168.0), k1y_w0);
