static void rk45_vector(int64_t *n_accept, int64_t *n_reject, double *y,
                        const double *y0, int64_t NSYS, double t_end) {
    const int64_t lanes = 8 * 2;
    const int64_t ngroups = (NSYS + lanes - 1) / lanes;
    #pragma omp parallel for schedule(dynamic,1)
    for (int64_t g = 0; g < ngroups; g++) {
        rk45_vec_group(y0, y, n_accept, n_reject, g * lanes, NSYS, t_end);
    }
}
#endif /* __AVX512F__ */

void rk45_ensemble_fp64(
    int64_t *restrict n_accept,
    int64_t *restrict n_reject,
    double *restrict y,
    const double *restrict y0,
    const int64_t NSYS,
    const double t_end,
    uint8_t *restrict workspace,
    const int64_t workspace_size) {
    (void)workspace; (void)workspace_size;
#if defined(__x86_64__) && defined(__AVX512F__)
    if (__builtin_cpu_supports("avx512f")) {
        rk45_vector(n_accept, n_reject, y, y0, NSYS, t_end);
        return;
    }
#endif
    rk45_scalar(n_accept, n_reject, y, y0, NSYS, t_end);
}
